import AnalogClock from './components/AnalogClock';
import DigitalReadout from './components/DigitalReadout';
import { useNow } from './hooks/useNow';

function App() {
  const now = useNow(1000);

  return (
    <div className="app">
      <h1>Analog Clock</h1>
      <AnalogClock date={now} />
      <DigitalReadout date={now} />
    </div>
  );
}

export default App;

