src/utils/getHandAngles.js.contents:
// Maps a Date to the rotation angle of each clock hand.
//
// All angles are measured clockwise from 12 o'clock and stay in [0, 360).
//
//   - minute hand: 360 degrees per 60 minutes  -> 6 degrees per minute
//   - hour hand:   360 degrees per 12 hours    -> 30 degrees per hour,
//                  plus a fractional contribution per elapsed minute so it
//                  glides between hour marks instead of jumping
//   - second hand: 360 degrees per 60 seconds  -> 6 degrees per second
//
// Example: at 12:00:00 every hand should return 0 (they all point at 12),
// never 360 or 720.

export function getHandAngles(date) {
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();

  // Minute hand: 6 degrees per minute, always whole degrees.
  const minuteDeg = minutes * 6;

  // Hour hand: 30 degrees per hour mark plus 0.5 degrees per elapsed minute
  // (the fractional part is what keeps the hour hand gliding smoothly).
  const hourDeg = (hours % 12) * 30;

  // TODO: implement the second hand rotation.
  // It completes one full turn (360 degrees) in 60 seconds, i.e. 6 degrees
  // per second. The second hand stays hidden until this returns a number.
  const secondDeg = null; // stub — replace with the real formula

  return { hourDeg, minuteDeg, secondDeg };
}

