import { getHandAngles } from '../utils/getHandAngles';

const TICK_COUNT = 12;

function buildTicks() {
  const ticks = [];
  for (let i = 0; i < TICK_COUNT; i += 1) {
    const deg = i * 30;
    const rad = (deg * Math.PI) / 180;
    const sin = Math.sin(rad);
    const cos = Math.cos(rad);
    const major = i % 3 === 0;
    const inner = major ? 81 : 85;
    ticks.push({
      key: i,
      x1: 100 + sin * inner,
      y1: 100 - cos * inner,
      x2: 100 + sin * 92,
      y2: 100 - cos * 92,
      strokeWidth: major ? 2 : 1,
    });
  }
  return ticks;
}

const TICKS = buildTicks();

// Renders an analog clock face and rotates each hand with getHandAngles().
// The second hand is painted only once its angle is a number, i.e. once
// getHandAngles has a working implementation.
export default function AnalogClock({ date }) {
  const { hourDeg, minuteDeg, secondDeg } = getHandAngles(date);

  return (
    <svg
      className="clock"
      viewBox="0 0 200 200"
      width="240"
      height="240"
      role="img"
      aria-label="Analog clock"
    >
      <circle className="clock-face" cx="100" cy="100" r="92" />
      {TICKS.map(({ x1, y1, x2, y2, strokeWidth, key }) => (
        <line
          key={key}
          className="ticks"
          x1={x1}
          y1={y1}
          x2={x2}
          y2={y2}
          strokeWidth={strokeWidth}
        />
      ))}
      <line
        className="hand hour-hand"
        x1={100}
        y1={100}
        x2={100}
        y2={36}
        transform={`rotate(${hourDeg} 100 100)`}
      />
      <line
        className="hand minute-hand"
        x1={100}
        y1={100}
        x2={100}
        y2={16}
        transform={`rotate(${minuteDeg} 100 100)`}
      />
      {typeof secondDeg === 'number' && (
        <line
          className="hand second-hand"
          x1={100}
          y1={118}
          x2={100}
          y2={14}
          transform={`rotate(${secondDeg} 100 100)`}
        />
      )}
      <circle className="clock-hub" cx="100" cy="100" r="3.5" />
    </svg>
  );
}

