import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import { getHandAngles } from '../src/utils/getHandAngles';
import App from '../src/App';

describe('Analog Clock', () => {
  test('at 12:00:00 every hand points straight at 12 (0 degrees)', () => {
    const { hourDeg, minuteDeg, secondDeg } = getHandAngles(new Date(2024, 0, 1, 12, 0, 0));
    if (secondDeg === null) {
      throw new Error('secondDeg is still the stub — implement the real formula in getHandAngles.js');
    }
    expect(hourDeg).toBe(0);
    expect(minuteDeg).toBe(0);
    expect(secondDeg).toBe(0);
  });

  test('at 3:00:00 the hour hand sits at 90 degrees', () => {
    const { hourDeg, minuteDeg } = getHandAngles(new Date(2024, 5, 15, 15, 0, 0));
    if (hourDeg !== 90) {
      throw new Error(`At 3:00 the hour hand should be at 90 degrees, got ${hourDeg}`);
    }
    if (minuteDeg !== 0) {
      throw new Error(`At 3:00 the minute hand should be at 0 degrees, got ${minuteDeg}`);
    }
  });

  test('the minute hand advances 6 degrees per minute', () => {
    const atQuarterPast = getHandAngles(new Date(2024, 0, 1, 10, 15, 0));
    const atQuarterTo = getHandAngles(new Date(2024, 0, 1, 10, 45, 0));
    if (atQuarterPast.minuteDeg !== 15 * 6) {
      throw new Error(`At quarter past the minute hand should be at 90 degrees, got ${atQuarterPast.minuteDeg}`);
    }
    if (atQuarterTo.minuteDeg !== 45 * 6) {
      throw new Error(`At quarter to the minute hand should be at 270 degrees, got ${atQuarterTo.minuteDeg}`);
    }
  });

  test('the second hand advances 6 degrees per second', () => {
    const { secondDeg } = getHandAngles(new Date(2024, 0, 1, 11, 32, 10));
    if (secondDeg === null) {
      throw new Error('secondDeg is still the stub — the second hand must complete 360 degrees in 60 seconds');
    }
    if (secondDeg !== 10 * 6) {
      throw new Error(`At 10 seconds the second hand should be at 60 degrees, got ${secondDeg}`);
    }
  });

  test('the hour hand glides between marks and wraps at 12', () => {
    const atOneThirty = getHandAngles(new Date(2024, 0, 1, 13, 30, 0));
    const atElevenThirty = getHandAngles(new Date(2024, 0, 1, 23, 30, 0));
    const atNoon = getHandAngles(new Date(2024, 0, 1, 12, 0, 0));
    if (atOneThirty.hourDeg !== 45) {
      throw new Error(`At 1:30 the hour hand should sit at 45 degrees (between 1 and 2), got ${atOneThirty.hourDeg}`);
    }
    if (atElevenThirty.hourDeg !== 345) {
      throw new Error(`At 23:30 the hour hand should be at 345 degrees (just before 12), got ${atElevenThirty.hourDeg}`);
    }
    if (atNoon.hourDeg !== 0) {
      throw new Error(`At 12:00 the hour hand should wrap back to 0, got ${atNoon.hourDeg}`);
    }
  });

  test('the preview mounts the clock face and both hour/minute hands', () => {
    const { container } = render(<App />);
    const heading = container.querySelector('h1');
    if (!heading || !heading.textContent.includes('Analog Clock')) {
      throw new Error('Expected an <h1> heading containing "Analog Clock"');
    }
    if (!container.querySelector('svg.clock')) {
      throw new Error('Expected an SVG element with class "clock"');
    }
    if (!container.querySelector('line.hour-hand')) {
      throw new Error('Expected a rendered hour hand');
    }
    if (!container.querySelector('line.minute-hand')) {
      throw new Error('Expected a rendered minute hand');
    }
  });
});
